            HWND_BOTTOM,
            0,
            0,
            0,
            0,
            SWP_HIDEWINDOW | SWP_NOACTIVATE | SWP_NOMOVE | SWP_NOSIZE,
        );
    }
    let _ = window.set_visible(false);
}

