                    if unsafe { GetForegroundWindow() } == hwnd {
                        let _ = window.set_visible(false);
                    }
                    crate::overlay::hotkey::release_mask_after_hide();
                    pending_resize = None;
                    if ready {
                        push_state(&webview, &state, &icon_cache, false);
                    }
                    if let Ok(mut s) = state.lock() {
                        s.has_focus = false;
                    }
