/// The shared, framework-agnostic snapshot of overlay state. The
/// [`crate::overlay::shim::NativeOverlayShell`] owns this behind an
/// `Arc<Mutex<>>`; the WebView host (`crate::overlay::host`) reads it
/// to build the JSON snapshot pushed to the web UI, and the IPC
/// handler writes back the live `query`/`selected` values so the
/// runtime's getters stay correct.
#[derive(Debug, Clone)]
pub struct ShimState {
    pub query: String,
    pub status_text: String,
    pub placeholder_hint: Option<String>,
    pub hotkey_hint: String,
    pub hotkey_issue_active: bool,
    pub game_mode_enabled: bool,
    pub grid_view: bool,
    pub theme: Theme,
    /// System accent color as `#RRGGBB` (from DWM AccentColor), if readable.
    pub accent_color: Option<String>,
    pub rows: Vec<OverlayRow>,
    pub selected: usize,
    pub visible: bool,
    pub has_focus: bool,
    pub hwnd: isize,
    pub chat_file_picker_open: bool,
    pub chat_file_picker_pending: bool,
    pub idle_cache_trim_ms: u32,
    pub active_memory_target_mb: u16,
    pub ui_warm_release_ms: u32,
    /// Quick Launch items for idle state (empty query).
    pub quick_launch_items: Vec<QuickLaunchItem>,
    /// Whether Quick Launch is visible (query is empty).
    pub quick_launch_visible: bool,
    /// Whether the bento grid view is active (clipboard history).
    pub bento_view: bool,
    /// Command-mode autofill: full title of the top matching command.
    /// The page renders the untyped remainder dimmed inside the input
    /// and Tab fills it in. `None` outside command mode.
    pub completion: Option<String>,
    /// Whether a new update is available. When true, show update notification.
    pub update_available: bool,
    /// Native glass layer active below the page: the page drops its own
    /// painted backgrounds so live pixels show through (spike).
    pub glass_native: bool,
    /// The renderer has presented a frame the layer can show. Until it
    /// has, the page keeps its opaque surface: transparency over a glass
    /// layer with nothing in it is a see-through panel, and a renderer
    /// that never comes up would leave the panel invisible.
    pub glass_frame_ready: bool,
    /// Whether the cursor is inside the panel at show. The page keeps the
    /// pointer position from the previous session to keep the selection
    /// under a stationary mouse; if the pointer is elsewhere, remembering
    /// it would re-select a row nobody is pointing at.
    pub pointer_over_panel: bool,
    /// The glass material is currently a light surface, so the page uses
    /// the light palette with dark text (vibrancy: the material follows
    /// the backdrop, and the text follows the material).
    pub glass_light: bool,
    /// Post-update version with unseen notes. When set, the update notice
    /// opens the What's New view instead of running an update check.
    pub whats_new_pending: Option<String>,
    /// Panel background mode: live glass, or an opaque black/white
    /// panel (glass layer parked, page paints solid).
    pub panel_background: crate::config::PanelBackground,
    /// First-show content still incoming (Quick Launch deferred by a busy
    /// indexer). The page holds its instant idle reveal and waits for the
    /// rows instead of flashing input-first then popping rows in.
    pub content_pending: bool,
}

impl Default for ShimState {
    fn default() -> Self {
        Self {
            query: String::new(),
            status_text: String::new(),
            placeholder_hint: None,
            hotkey_hint: "Ctrl+Space".into(),
            hotkey_issue_active: false,
            game_mode_enabled: false,
            grid_view: false,
            theme: Theme::Dark,
            accent_color: None,
            rows: Vec::new(),
            selected: 0,
            visible: false,
            has_focus: false,
            hwnd: 0,
            chat_file_picker_open: false,
            chat_file_picker_pending: false,
            idle_cache_trim_ms: 90_000,
            active_memory_target_mb: 72,
            ui_warm_release_ms: 5_000,
            quick_launch_items: Vec::new(),
            quick_launch_visible: false,
            bento_view: false,
            completion: None,
            update_available: false,
            whats_new_pending: None,
            glass_native: false,
            pointer_over_panel: false,
            glass_frame_ready: false,
            glass_light: false,
            panel_background: crate::config::PanelBackground::Black,
            content_pending: false,
        }
    }
}

