            // r.path is the display subtitle (publisher name for UWP apps).
            // Start-menu shortcuts arrive as shell:AppsFolder\{GUID}\… URIs;
            // clients launching / copying / locating files need the real
            // path when one exists.
            let raw_target = r.icon_path.trim().to_string();
            let resolved = if raw_target.is_empty() {
                None
            } else {
                crate::action_executor::resolve_shell_appsfolder_path(&raw_target)
            };
            let file_path = if raw_target.is_empty() {
                serde_json::Value::Null
            } else {
                serde_json::Value::String(resolved.unwrap_or(raw_target))
            };
            let tile_size = r.tile_size.as_ref().map(|t| match t {
                TileSize::Small => "small",
                TileSize::Medium => "medium",
                TileSize::Large => "large",
            });
            serde_json::json!({
                "role": role,
                "title": r.title,
                "subtitle": r.path,
                "kind": r.kind,
                "url": r.url.clone(),
                // Canonical index identity for pin/unpin. `filePath` is the
                // resolved launch target (real path); pinning must use the
                // path the item was indexed under or the lookup misses and
                // resolves to an unrelated file/folder.
                "pinPath": match r.url.as_deref() {
                    Some(url) if !url.is_empty() => url.to_string(),
                    _ => r.icon_path.clone(),
                },
                "icon": icon,
                "filePath": file_path,
                "selectable": selectable,
                "resultIndex": r.result_index,
                "clipboardThumbnail": r.clipboard_thumbnail,
                "clipboardFullImage": r.clipboard_full_image,
                "tileSize": tile_size,
                "commandKind": r.command_kind,
                "launchCount": r.launch_count,
                "lastLaunchedAt": r.last_launched_at,
            })
        })
        .collect();

    let theme = match s.theme {
        Theme::Dark => "dark",
        Theme::Light => "light",
    };

    // Include Quick Launch items for idle state
    let quick_launch: Vec<serde_json::Value> = s
        .quick_launch_items
        .iter()
        .map(|item| {
            serde_json::json!({
                "title": item.title,
                "path": item.path,
                "url": if item.kind.eq_ignore_ascii_case("bookmark") { item.path.clone() } else { String::new() },
                "kind": item.kind,
                "icon": item.icon_path,
                "pinned": item.is_pinned,
            })
        })
        .collect();

    serde_json::json!({
        "query": s.query,
        "rows": rows,
        "selected": s.selected,
        "status": s.status_text,
        "placeholder": s.placeholder_hint,
        "hotkeyHint": s.hotkey_hint,
        "hotkeyIssue": s.hotkey_issue_active,
        "theme": theme,
        "accent": s.accent_color,
        "gridView": s.grid_view,
        "bentoView": s.bento_view,
        "completion": s.completion,
        "showPending": show_pending,
        "contentPending": s.content_pending,
        "quickLaunch": quick_launch,
        "quickLaunchVisible": s.quick_launch_visible,
        "updateAvailable": s.update_available,
        "whatsNewPending": s.whats_new_pending,
        "overlayVisible": s.visible,
        "pointerOverPanel": s.pointer_over_panel,
        "panelBackground": background,
        "opaqueDwmFrame": background != "glass"
            && OPAQUE_DWM_FRAME_ACTIVE.load(Ordering::SeqCst),
        "glassNative": transparent && s.glass_native && s.glass_frame_ready && !s.panel_background.is_opaque(),
        "glassLight": transparent && s.glass_native && s.glass_light,
        "glassClip": &*LENS_CLIP,
    })
    .to_string()
}

