    /// Write the rounded silhouette to the main window, unless that exact
    /// size/scale is already applied (a repeated sync must not rebuild the
    /// GDI region).
    fn apply_region(&self, w: u32, h: u32, scale: f64) {
        let key = (w, h, scale.to_bits());
        if self.window.region.get() == Some(key) {
            return;
        }
        apply_lens_region(self.main_sys, w, h, scale, SILHOUETTE_GROW_PX);
        apply_glass_region(self.window.hwnd.0 as isize, w, h);
        self.window.region.set(Some(key));
    }

    /// Record that the renderer presented a frame at `w`x`h`.
    pub fn note_frame(&self, w: u32, h: u32) {
        self.window.last_frame.set(Some((w, h)));
    }

    /// Lift the cloak once a frame for the panel's *current* size has been
    /// presented. A frame for the previous size leaves the rows the page
    /// just grew into holding older pixels, so this waits for the resize
    /// pass's own ack instead. Returns true only on the call that reveals;
    /// `set_visible(false)` re-arms it.
    pub fn reveal(&self) -> bool {
        if self.revealed.get() || !self.ready.load(Ordering::Acquire) {
            return false;
        }
        match self.window.last_region.get() {
            Some((w, h, bits)) if self.window.last_frame.get() == Some((w, h)) => {
                self.apply_region(w, h, f64::from_bits(bits));
                self.revealed.set(true);
                self.window.show(true);
                // The panel is on screen: the settle starts here, so the
                // spring the user sees is the whole animation rather than
                // whatever is left of it after the page finished painting.
                let _ = self.tx.send(GlassConfig {
                    visible: None,
                    main_sys: 0,
                    max_wh: None,
                    panel_wh: None,
                    theme_dark: None,
                    scale: None,
                    revealed: true,
                });
                crate::logging::info(&format!("[nex][refract] glass revealed {w}x{h}"));
                true
            }
            // A frame for another size: the resize pass acks again.
            _ => false,
        }
    }

    pub fn is_ready(&self) -> bool {
        self.ready.load(Ordering::Acquire)
    }
}

