      $entry = $zip.Entries | Where-Object { $_.Name -eq $EverythingDllName } | Select-Object -First 1
      if ($entry) {
        [System.IO.Compression.ZipFileExtensions]::ExtractToFile($entry, $everythingDllPath, $true)
        $extracted = $true
      }
      $zip.Dispose()
    } catch {
