  function renderWhatsNewMarkdown(md) {
    const items = [];
    let count = 0;
    for (const raw of md.split("\n")) {
      const line = raw.trim();
      if (!line || count >= 10) continue;
      if (/^#{2,4}\s/.test(line)) {
        items.push({ h: line.replace(/^#{2,4}\s*/, "") });
        continue;
      }
      if (/^[-*]\s/.test(line)) {
        items.push({ li: line.replace(/^[-*]\s*/, "") });
        count++;
